import pathlib; __file__=str(pathlib.Path(__file__).resolve()); exec(open(pathlib.Path(__file__).parent/'base.py').read())
# Onglet « Modules » de l'Administration (10/10/2026) : tous les modules, toutes spécialités confondues ; filtres ; packs et cabinets.
ok = lambda c, m: print(('✅ ' if c else '❌ ') + m)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pa = await ouvrir(b, S); await pa.add_init_script("""window.__uid='ADM';window.__fs['administrateurs/ADM']={email:'a@b.ma'};window.__fonctions={listeCabinets:async()=>({cabinets:[{id:'cabinet-bentahila',nom:'Cabinet B',cree:'2026-10-01',actif:true,titulaire:{},membres:4,patients:60},{id:'cab-t',nom:'Cabinet T',cree:'2026-10-09',actif:true,titulaire:{},membres:1,patients:0,abonnement:{formule:'essentiel',modules:{chimio:true,agenda:true,prescriptions:true,documents:true,listes:true,gagenda:true,bilan:true}}}]})};""")
        await pa.goto(f'http://localhost:{PORT}/admin.html#modules'); await pa.wait_for_timeout(1500)
        t = await pa.inner_text('#page'); n = await pa.evaluate("document.querySelectorAll('[data-module]').length")
        ok('Modules d\'Onco360' in t and n == 7 + 11 + 2, 'onglet Modules : 7 de base + 11 activables + 2 prévus = ' + str(n))
        ok(all(x in t for x in ['Bilan financier', 'Radiothérapie', 'Chimiothérapie et protocoles', 'Paramètres (paramétrage)', 'Traitements et stocks']), 'finance, radiothérapie, chimiothérapie, paramétrage, modules prévus listés')
        row = lambda k: pa.inner_text(f'[data-module="{k}"]')
        ok('Oncologie – Radiothérapie' in await row('rt') and 'Toutes' in await row('bilan') and 'Médecine générale' in await row('stocks'), 'spécialité de chaque module (RT : oncologie ; bilan : toutes ; stocks : médecine générale)')
        r = await row('rt'); ok(r.strip().endswith('1'), 'radiothérapie : 1 cabinet (le cabinet sans abonnement a tout, l\'Essentiel n\'a pas la RT) ' + r[-20:].replace('\n', ' '))
        await pa.evaluate("document.querySelector('[data-module=\"chimio\"] details').open=true"); r = await row('chimio')
        ok('Bibliothèque de protocoles' in r and '(de base)' in r and 'Calcul des doses' in r, 'fonctions de la chimiothérapie (dont protocoles, fonctions de base marquées)')
        await pa.click('[data-mg="base"]'); await pa.wait_for_timeout(200)
        ok(await pa.evaluate("document.querySelectorAll('[data-module]').length") == 7, 'filtre « De base » : 7')
        await pa.click('[data-mg=""]'); await pa.select_option('#mSpe', 'Médecine générale'); await pa.wait_for_timeout(200)
        ks = await pa.evaluate("[...document.querySelectorAll('[data-module]')].map(e=>e.dataset.module)")
        ok('chimio' not in ks and 'rt' not in ks and 'stocks' in ks and 'bilan' in ks, 'filtre Médecine générale : sans chimio ni RT, avec les modules communs et prévus')
        await pa.select_option('#mSpe', ''); await pa.fill('#mQ', 'dosim'); await pa.wait_for_timeout(200)
        ok(await pa.evaluate("[...document.querySelectorAll('[data-module]')].map(e=>e.dataset.module)") == ['rt'], 'recherche « dosim » : Radiothérapie')
        await pa.set_viewport_size({'width': 390, 'height': 800}); await pa.fill('#mQ', ''); await pa.wait_for_timeout(300)
        ok(await pa.evaluate("document.documentElement.scrollWidth<=390"), 'à 390 px : rien ne déborde')
        ok(not pa.errs, 'aucune erreur JavaScript ' + str(pa.errs[:2]))
        await b.close()
asyncio.run(main())
